insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-f1-champions-trivia',
  'F1 Champions Trivia: Titles and Key Seasons',
  'Eight questions on Formula 1 world champions: record-breaking seasons, the closest title finishes and the drivers who defined each era.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"Who is the only driver to have won the Formula 1 world championship posthumously?","options":[{"id":"a","text":"Jim Clark","is_correct":false},{"id":"b","text":"Jochen Rindt","is_correct":true},{"id":"c","text":"Graham Hill","is_correct":false},{"id":"d","text":"Gilles Villeneuve","is_correct":false}],"explanation":"Austrian Jochen Rindt died at Monza in September 1970 and clinched the title when no rival could catch his points total."},{"id":"q2","question":"Who became the youngest world champion in Formula 1 history in 2010?","options":[{"id":"a","text":"Lewis Hamilton","is_correct":false},{"id":"b","text":"Fernando Alonso","is_correct":false},{"id":"c","text":"Sebastian Vettel","is_correct":true},{"id":"d","text":"Max Verstappen","is_correct":false}],"explanation":"Vettel was 23 years and 134 days old when he won the 2010 Abu Dhabi finale, breaking Hamilton''s record."},{"id":"q3","question":"How many drivers'' world championships did Alain Prost win?","options":[{"id":"a","text":"Two","is_correct":false},{"id":"b","text":"Three","is_correct":false},{"id":"c","text":"Five","is_correct":false},{"id":"d","text":"Four","is_correct":true}],"explanation":"Prost won in 1985, 1986, 1989 and 1993, for McLaren and Williams."},{"id":"q4","question":"Which driver won the 2009 world title with Brawn GP, in the team''s only season?","options":[{"id":"a","text":"Jenson Button","is_correct":true},{"id":"b","text":"Rubens Barrichello","is_correct":false},{"id":"c","text":"Jarno Trulli","is_correct":false},{"id":"d","text":"Nico Rosberg","is_correct":false}],"explanation":"Button won six of the first seven races and sealed the title in Brazil; Brawn became Mercedes in 2010."},{"id":"q5","question":"By what margin did Niki Lauda beat Alain Prost in the 1984 championship, the closest in F1 history?","options":[{"id":"a","text":"One point","is_correct":false},{"id":"b","text":"Half a point","is_correct":true},{"id":"c","text":"Three points","is_correct":false},{"id":"d","text":"Seven points","is_correct":false}],"explanation":"Lauda finished with 72 points to Prost''s 71.5 — a half-point gap that remains the smallest ever."},{"id":"q6","question":"Who won the 2021 world championship on the last lap of the Abu Dhabi Grand Prix?","options":[{"id":"a","text":"Lewis Hamilton","is_correct":false},{"id":"b","text":"Charles Leclerc","is_correct":false},{"id":"c","text":"Max Verstappen","is_correct":true},{"id":"d","text":"Sergio Pérez","is_correct":false}],"explanation":"Verstappen passed Hamilton on the final lap at Yas Marina to take his first title."},{"id":"q7","question":"Which driver retired five days after winning the 2016 world championship?","options":[{"id":"a","text":"Jenson Button","is_correct":false},{"id":"b","text":"Nico Rosberg","is_correct":true},{"id":"c","text":"Kimi Räikkönen","is_correct":false},{"id":"d","text":"Sebastian Vettel","is_correct":false}],"explanation":"Rosberg beat teammate Hamilton to the 2016 title and announced his retirement five days later."},{"id":"q8","question":"Which driver won back-to-back titles for Ferrari in 1952 and 1953?","options":[{"id":"a","text":"Juan Manuel Fangio","is_correct":false},{"id":"b","text":"Mike Hawthorn","is_correct":false},{"id":"c","text":"Giuseppe Farina","is_correct":false},{"id":"d","text":"Alberto Ascari","is_correct":true}],"explanation":"Ascari dominated 1952-53 for Ferrari and remains the last Italian to win the championship."}]'::jsonb,
  null,
  array['formula 1', 'f1', 'world champions', 'f1 history', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
