values (
  'es-trivia-campeones-de-f1',
  'Trivia de campeones de F1: títulos y temporadas',
  'Ocho preguntas sobre los campeones del mundo de Fórmula 1: temporadas récord, finales ajustados y los pilotos que marcaron cada época.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"¿Quién es el único piloto que ganó el campeonato mundial de Fórmula 1 a título póstumo?","options":[{"id":"a","text":"Jim Clark","is_correct":false},{"id":"b","text":"Jochen Rindt","is_correct":true},{"id":"c","text":"Graham Hill","is_correct":false},{"id":"d","text":"Gilles Villeneuve","is_correct":false}],"explanation":"El austríaco Jochen Rindt murió en Monza en septiembre de 1970 y se coronó cuando ningún rival pudo alcanzar su puntaje."},{"id":"q2","question":"¿Quién se convirtió en 2010 en el campeón del mundo más joven de la historia de la Fórmula 1?","options":[{"id":"a","text":"Lewis Hamilton","is_correct":false},{"id":"b","text":"Fernando Alonso","is_correct":false},{"id":"c","text":"Sebastian Vettel","is_correct":true},{"id":"d","text":"Max Verstappen","is_correct":false}],"explanation":"Vettel tenía 23 años y 134 días cuando ganó la final de Abu Dabi 2010, superando el récord de Hamilton."},{"id":"q3","question":"¿Cuántos campeonatos del mundo de pilotos ganó Alain Prost?","options":[{"id":"a","text":"Dos","is_correct":false},{"id":"b","text":"Tres","is_correct":false},{"id":"c","text":"Cinco","is_correct":false},{"id":"d","text":"Cuatro","is_correct":true}],"explanation":"Prost se coronó en 1985, 1986, 1989 y 1993, con McLaren y Williams."},{"id":"q4","question":"¿Qué piloto ganó el título de 2009 con Brawn GP, en la única temporada del equipo?","options":[{"id":"a","text":"Jenson Button","is_correct":true},{"id":"b","text":"Rubens Barrichello","is_correct":false},{"id":"c","text":"Jarno Trulli","is_correct":false},{"id":"d","text":"Nico Rosberg","is_correct":false}],"explanation":"Button ganó seis de las primeras siete carreras y selló el título en Brasil; Brawn se convirtió en Mercedes en 2010."},{"id":"q5","question":"¿Por qué margen le ganó Niki Lauda a Alain Prost el campeonato de 1984, el más ajustado de la historia?","options":[{"id":"a","text":"Un punto","is_correct":false},{"id":"b","text":"Medio punto","is_correct":true},{"id":"c","text":"Tres puntos","is_correct":false},{"id":"d","text":"Siete puntos","is_correct":false}],"explanation":"Lauda terminó con 72 puntos contra 71,5 de Prost, una diferencia que sigue siendo la menor de la historia."},{"id":"q6","question":"¿Quién ganó el campeonato de 2021 en la última vuelta del Gran Premio de Abu Dabi?","options":[{"id":"a","text":"Lewis Hamilton","is_correct":false},{"id":"b","text":"Charles Leclerc","is_correct":false},{"id":"c","text":"Max Verstappen","is_correct":true},{"id":"d","text":"Sergio Pérez","is_correct":false}],"explanation":"Verstappen superó a Hamilton en la vuelta final de Yas Marina y obtuvo su primer título."},{"id":"q7","question":"¿Qué piloto se retiró cinco días después de ganar el campeonato de 2016?","options":[{"id":"a","text":"Jenson Button","is_correct":false},{"id":"b","text":"Nico Rosberg","is_correct":true},{"id":"c","text":"Kimi Räikkönen","is_correct":false},{"id":"d","text":"Sebastian Vettel","is_correct":false}],"explanation":"Rosberg le ganó el título de 2016 a su compañero Hamilton y anunció su retiro cinco días después."},{"id":"q8","question":"¿Qué piloto ganó títulos consecutivos con Ferrari en 1952 y 1953?","options":[{"id":"a","text":"Juan Manuel Fangio","is_correct":false},{"id":"b","text":"Mike Hawthorn","is_correct":false},{"id":"c","text":"Giuseppe Farina","is_correct":false},{"id":"d","text":"Alberto Ascari","is_correct":true}],"explanation":"Ascari dominó 1952 y 1953 con Ferrari y sigue siendo el último italiano en ganar el campeonato."}]'::jsonb,
  null,
  array['fórmula 1', 'f1', 'campeones del mundo', 'historia de la f1', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
