insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-f1-circuits-trivia',
  'F1 Circuits Trivia: Monaco, Monza, Spa and More',
  'Eight questions on Formula 1''s legendary tracks: Monaco''s streets, Monza''s speed, Spa''s Eau Rouge, Suzuka''s figure eight and Interlagos.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"What is the name of the famous uphill sweep at Spa-Francorchamps?","options":[{"id":"a","text":"Eau Rouge–Raidillon","is_correct":true},{"id":"b","text":"130R","is_correct":false},{"id":"c","text":"Parabolica","is_correct":false},{"id":"d","text":"Maggotts and Becketts","is_correct":false}],"explanation":"Eau Rouge and Raidillon form the steep left-right-left climb just after the start at the Belgian circuit."},{"id":"q2","question":"Which circuit is the only figure-eight layout on the Formula 1 calendar?","options":[{"id":"a","text":"Silverstone","is_correct":false},{"id":"b","text":"Circuit of the Americas","is_correct":false},{"id":"c","text":"Suzuka","is_correct":true},{"id":"d","text":"Red Bull Ring","is_correct":false}],"explanation":"Suzuka''s figure-eight layout includes a bridge where the back straight crosses over the rest of the lap."},{"id":"q3","question":"Interlagos, home of the São Paulo Grand Prix, is officially named after which Brazilian driver?","options":[{"id":"a","text":"Emerson Fittipaldi","is_correct":false},{"id":"b","text":"Nelson Piquet","is_correct":false},{"id":"c","text":"Ayrton Senna","is_correct":false},{"id":"d","text":"José Carlos Pace","is_correct":true}],"explanation":"The Autódromo José Carlos Pace honours the Brazilian winner of the 1975 Brazilian Grand Prix, who died in 1977."},{"id":"q4","question":"Which circuit hosted the very first Formula 1 world championship race, in 1950?","options":[{"id":"a","text":"Silverstone","is_correct":true},{"id":"b","text":"Monaco","is_correct":false},{"id":"c","text":"Monza","is_correct":false},{"id":"d","text":"Spa-Francorchamps","is_correct":false}],"explanation":"The 1950 British Grand Prix at Silverstone, a former airfield, opened the championship on 13 May 1950."},{"id":"q5","question":"The Nürburgring Nordschleife, nicknamed the ''Green Hell'', last hosted a Grand Prix in which year?","options":[{"id":"a","text":"1969","is_correct":false},{"id":"b","text":"1985","is_correct":false},{"id":"c","text":"1994","is_correct":false},{"id":"d","text":"1976","is_correct":true}],"explanation":"After Niki Lauda''s fiery 1976 crash, F1 never raced again on the 20-kilometre Nordschleife."},{"id":"q6","question":"Where did Formula 1 hold its first night race, in 2008?","options":[{"id":"a","text":"Bahrain","is_correct":false},{"id":"b","text":"Singapore","is_correct":true},{"id":"c","text":"Abu Dhabi","is_correct":false},{"id":"d","text":"Las Vegas","is_correct":false}],"explanation":"The 2008 Singapore Grand Prix at Marina Bay was the first F1 race run entirely under floodlights."},{"id":"q7","question":"The slowest corner in Formula 1, the Monaco hairpin, is named after which hotel?","options":[{"id":"a","text":"Hôtel de Paris","is_correct":false},{"id":"b","text":"Hôtel Hermitage","is_correct":false},{"id":"c","text":"Fairmont","is_correct":true},{"id":"d","text":"Monte-Carlo Bay","is_correct":false}],"explanation":"The hairpin by the Fairmont hotel — long known as the Loews — is taken at barely 50 km/h."},{"id":"q8","question":"Montreal''s Circuit Gilles Villeneuve is famous for which feature at the final chicane?","options":[{"id":"a","text":"The Corkscrew","is_correct":false},{"id":"b","text":"The Wall of Champions","is_correct":true},{"id":"c","text":"The Karussell","is_correct":false},{"id":"d","text":"The Snake","is_correct":false}],"explanation":"The ''Wall of Champions'' claimed Schumacher, Hill and Villeneuve in the 1999 race alone."}]'::jsonb,
  null,
  array['formula 1', 'f1', 'circuits', 'grand prix', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
