values (
  'es-trivia-circuitos-de-f1',
  'Trivia de circuitos de F1: Mónaco, Monza, Spa y más',
  'Ocho preguntas sobre los circuitos míticos de la Fórmula 1: las calles de Mónaco, la velocidad de Monza, Eau Rouge, Suzuka e Interlagos.',
  'trivia',
  'medium',
  'es',
