  '[{"id":"q1","question":"¿Cómo se llama la famosa subida en curva de Spa-Francorchamps?","options":[{"id":"a","text":"Eau Rouge–Raidillon","is_correct":true},{"id":"b","text":"130R","is_correct":false},{"id":"c","text":"Parabolica","is_correct":false},{"id":"d","text":"Maggotts y Becketts","is_correct":false}],"explanation":"Eau Rouge y Raidillon forman la empinada secuencia izquierda-derecha-izquierda tras la salida del circuito belga."},{"id":"q2","question":"¿Cuál es el único circuito del calendario de Fórmula 1 con trazado en forma de ocho?","options":[{"id":"a","text":"Silverstone","is_correct":false},{"id":"b","text":"Circuito de las Américas","is_correct":false},{"id":"c","text":"Suzuka","is_correct":true},{"id":"d","text":"Red Bull Ring","is_correct":false}],"explanation":"El ocho de Suzuka incluye un puente donde la recta trasera cruza por encima del resto de la vuelta."},{"id":"q3","question":"Interlagos, sede del Gran Premio de São Paulo, lleva oficialmente el nombre de qué piloto brasileño?","options":[{"id":"a","text":"Emerson Fittipaldi","is_correct":false},{"id":"b","text":"Nelson Piquet","is_correct":false},{"id":"c","text":"Ayrton Senna","is_correct":false},{"id":"d","text":"José Carlos Pace","is_correct":true}],"explanation":"El Autódromo José Carlos Pace honra al brasileño que ganó su gran premio de casa en 1975 y murió en 1977."},{"id":"q4","question":"¿Qué circuito albergó la primera carrera del campeonato mundial de Fórmula 1, en 1950?","options":[{"id":"a","text":"Silverstone","is_correct":true},{"id":"b","text":"Mónaco","is_correct":false},{"id":"c","text":"Monza","is_correct":false},{"id":"d","text":"Spa-Francorchamps","is_correct":false}],"explanation":"El Gran Premio de Gran Bretaña de 1950 en Silverstone, un antiguo aeródromo, inauguró el campeonato el 13 de mayo."},{"id":"q5","question":"¿En qué año se corrió el último Gran Premio en la Nordschleife de Nürburgring, el «Infierno Verde»?","options":[{"id":"a","text":"1969","is_correct":false},{"id":"b","text":"1985","is_correct":false},{"id":"c","text":"1994","is_correct":false},{"id":"d","text":"1976","is_correct":true}],"explanation":"Tras el accidente en llamas de Niki Lauda en 1976, la F1 no volvió a correr en el trazado de 20 kilómetros."},{"id":"q6","question":"¿Dónde se disputó la primera carrera nocturna de la Fórmula 1, en 2008?","options":[{"id":"a","text":"Baréin","is_correct":false},{"id":"b","text":"Singapur","is_correct":true},{"id":"c","text":"Abu Dabi","is_correct":false},{"id":"d","text":"Las Vegas","is_correct":false}],"explanation":"El Gran Premio de Singapur de 2008 en Marina Bay fue la primera carrera de F1 disputada por completo bajo focos."},{"id":"q7","question":"La curva más lenta de la Fórmula 1, la horquilla de Mónaco, lleva el nombre de qué hotel?","options":[{"id":"a","text":"Hôtel de Paris","is_correct":false},{"id":"b","text":"Hôtel Hermitage","is_correct":false},{"id":"c","text":"Fairmont","is_correct":true},{"id":"d","text":"Monte-Carlo Bay","is_correct":false}],"explanation":"La horquilla junto al hotel Fairmont, antes conocida como Loews, se toma a apenas 50 km/h."},{"id":"q8","question":"¿Por qué elemento es famosa la última chicana del Circuit Gilles Villeneuve de Montreal?","options":[{"id":"a","text":"El Sacacorchos","is_correct":false},{"id":"b","text":"El Muro de los Campeones","is_correct":true},{"id":"c","text":"El Karussell","is_correct":false},{"id":"d","text":"La Serpiente","is_correct":false}],"explanation":"El «Muro de los Campeones» atrapó a Schumacher, Hill y Villeneuve solo en la carrera de 1999."}]'::jsonb,
  null,
  array['fórmula 1', 'f1', 'circuitos', 'gran premio', 'trivia']::text[],
