insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-f1-teams-trivia',
  'F1 Teams Trivia: Ferrari, McLaren, Williams and More',
  'Eight questions on the great Formula 1 constructors: Ferrari''s longevity, McLaren''s origins, Williams'' independence and the Mercedes era.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"Which is the only team to have competed in every Formula 1 season since 1950?","options":[{"id":"a","text":"Ferrari","is_correct":true},{"id":"b","text":"McLaren","is_correct":false},{"id":"c","text":"Williams","is_correct":false},{"id":"d","text":"Mercedes","is_correct":false}],"explanation":"Ferrari has been on the grid since the first championship in 1950; McLaren and Williams did not yet exist."},{"id":"q2","question":"Who founded the McLaren team?","options":[{"id":"a","text":"Ron Dennis","is_correct":false},{"id":"b","text":"Bruce McLaren","is_correct":true},{"id":"c","text":"Teddy Mayer","is_correct":false},{"id":"d","text":"John Cooper","is_correct":false}],"explanation":"New Zealand driver Bruce McLaren founded the team in 1963; Ron Dennis took over in 1980."},{"id":"q3","question":"Frank Williams founded Williams Grand Prix Engineering in 1977 together with which engineer?","options":[{"id":"a","text":"Adrian Newey","is_correct":false},{"id":"b","text":"Ross Brawn","is_correct":false},{"id":"c","text":"Patrick Head","is_correct":true},{"id":"d","text":"Gordon Murray","is_correct":false}],"explanation":"Williams and co-founder Patrick Head won their first titles in 1980 with Alan Jones."},{"id":"q4","question":"How many consecutive constructors'' championships did Mercedes win between 2014 and 2021?","options":[{"id":"a","text":"Five","is_correct":false},{"id":"b","text":"Eight","is_correct":true},{"id":"c","text":"Six","is_correct":false},{"id":"d","text":"Ten","is_correct":false}],"explanation":"Mercedes won eight constructors'' titles in a row from 2014 to 2021, a record streak."},{"id":"q5","question":"Red Bull Racing entered Formula 1 in 2005 by buying which existing team?","options":[{"id":"a","text":"Jordan","is_correct":false},{"id":"b","text":"Sauber","is_correct":false},{"id":"c","text":"Lotus","is_correct":false},{"id":"d","text":"Jaguar","is_correct":true}],"explanation":"Red Bull bought Jaguar from Ford and turned it into a race winner by 2009 and champion in 2010."},{"id":"q6","question":"Which team won both 2009 championships in its only season of competition?","options":[{"id":"a","text":"Brawn GP","is_correct":true},{"id":"b","text":"Toyota","is_correct":false},{"id":"c","text":"Force India","is_correct":false},{"id":"d","text":"Super Aguri","is_correct":false}],"explanation":"Formed from the remains of Honda, Brawn GP won both titles in 2009 and was sold to Mercedes."},{"id":"q7","question":"Who is the only driver to win the world championship in a car bearing his own name?","options":[{"id":"a","text":"Bruce McLaren","is_correct":false},{"id":"b","text":"John Surtees","is_correct":false},{"id":"c","text":"Jack Brabham","is_correct":true},{"id":"d","text":"Graham Hill","is_correct":false}],"explanation":"Brabham won the 1966 title driving a Brabham-Repco built by his own team."},{"id":"q8","question":"Who was Ferrari''s most recent drivers'' world champion, crowned in 2007?","options":[{"id":"a","text":"Michael Schumacher","is_correct":false},{"id":"b","text":"Kimi Räikkönen","is_correct":true},{"id":"c","text":"Fernando Alonso","is_correct":false},{"id":"d","text":"Felipe Massa","is_correct":false}],"explanation":"Räikkönen beat McLaren teammates Hamilton and Alonso by one point at the 2007 finale."}]'::jsonb,
  null,
  array['formula 1', 'f1', 'teams', 'ferrari', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
