insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-f1-2026-rules-trivia',
  'F1 2026 Rules Trivia: New Engines and Active Aero',
  'Eight questions on Formula 1''s 2026 regulations: sustainable fuel, active aerodynamics, the new power split and Cadillac''s arrival.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"Which overtaking aid replaces DRS under the 2026 regulations?","options":[{"id":"a","text":"Attack Mode","is_correct":false},{"id":"b","text":"Manual Override Mode","is_correct":true},{"id":"c","text":"Overboost System","is_correct":false},{"id":"d","text":"Slipstream Mode","is_correct":false}],"explanation":"From 2026, a driver within a second of the car ahead can deploy extra electrical energy via the Manual Override Mode."},{"id":"q2","question":"Roughly what proportion of the 2026 power unit''s output comes from the electric motor?","options":[{"id":"a","text":"About a quarter","is_correct":false},{"id":"b","text":"About two thirds","is_correct":false},{"id":"c","text":"About half","is_correct":true},{"id":"d","text":"Nearly all of it","is_correct":false}],"explanation":"The 2026 rules target a near 50/50 split, with the MGU-K''s power raised to 350 kW."},{"id":"q3","question":"Which component disappears from the hybrid power unit in 2026?","options":[{"id":"a","text":"The MGU-H","is_correct":true},{"id":"b","text":"The MGU-K","is_correct":false},{"id":"c","text":"The turbocharger","is_correct":false},{"id":"d","text":"The energy store","is_correct":false}],"explanation":"The complex MGU-H, which recovered energy from the turbo, is dropped for 2026 while the MGU-K gains power."},{"id":"q4","question":"What fuel must the 2026 cars run?","options":[{"id":"a","text":"E10 with 10% ethanol","is_correct":false},{"id":"b","text":"100% sustainable fuel","is_correct":true},{"id":"c","text":"Synthetic diesel","is_correct":false},{"id":"d","text":"Standard pump petrol","is_correct":false}],"explanation":"The 2026 power units run on fully sustainable ''drop-in'' fuel developed under FIA rules."},{"id":"q5","question":"Which brand joins the grid as the eleventh Formula 1 team in 2026?","options":[{"id":"a","text":"Porsche","is_correct":false},{"id":"b","text":"Toyota","is_correct":false},{"id":"c","text":"Cadillac","is_correct":true},{"id":"d","text":"BMW","is_correct":false}],"explanation":"General Motors'' Cadillac entry was approved as the eleventh team, initially running Ferrari power units."},{"id":"q6","question":"Audi becomes a works Formula 1 team in 2026 by taking over which outfit?","options":[{"id":"a","text":"Haas","is_correct":false},{"id":"b","text":"Sauber","is_correct":true},{"id":"c","text":"Williams","is_correct":false},{"id":"d","text":"Racing Bulls","is_correct":false}],"explanation":"Audi took full control of the Sauber organisation, which races under the Audi name from 2026."},{"id":"q7","question":"What do the 2026 cars'' movable front and rear wings provide?","options":[{"id":"a","text":"Ground effect venturi tunnels","is_correct":false},{"id":"b","text":"Automatic brake balance","is_correct":false},{"id":"c","text":"Active aerodynamics for straights and corners","is_correct":true},{"id":"d","text":"A complete ban on wing adjustments","is_correct":false}],"explanation":"Both wings open on the straights (X-mode) and close for corners (Z-mode) to cut drag without losing downforce."},{"id":"q8","question":"Compared with the previous generation, the 2026 cars are designed to be…","options":[{"id":"a","text":"Larger and heavier","is_correct":false},{"id":"b","text":"Identical in size","is_correct":false},{"id":"c","text":"Two metres longer","is_correct":false},{"id":"d","text":"Smaller and roughly 30 kg lighter","is_correct":true}],"explanation":"The ''nimble car'' concept shrinks dimensions and cuts the minimum weight by about 30 kg."}]'::jsonb,
  null,
  array['formula 1', 'f1', '2026 regulations', 'new rules', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-reglamento-f1-2026',
  'Trivia del reglamento de F1 2026: motores y aerodinámica',
  'Ocho preguntas sobre el reglamento 2026 de la Fórmula 1: combustible sostenible, aerodinámica activa, nuevo reparto de potencia y Cadillac.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"¿Qué ayuda al adelantamiento reemplaza al DRS en el reglamento de 2026?","options":[{"id":"a","text":"Attack Mode","is_correct":false},{"id":"b","text":"Manual Override Mode","is_correct":true},{"id":"c","text":"Sistema Overboost","is_correct":false},{"id":"d","text":"Modo rebufo","is_correct":false}],"explanation":"Desde 2026, quien esté a menos de un segundo del coche de delante puede desplegar energía eléctrica extra con el Manual Override Mode."},{"id":"q2","question":"¿Qué proporción de la potencia del motor de 2026, aproximadamente, es eléctrica?","options":[{"id":"a","text":"Cerca de una cuarta parte","is_correct":false},{"id":"b","text":"Cerca de dos tercios","is_correct":false},{"id":"c","text":"Cerca de la mitad","is_correct":true},{"id":"d","text":"Casi toda","is_correct":false}],"explanation":"El reglamento 2026 busca un reparto cercano al 50/50, con la potencia del MGU-K elevada a 350 kW."},{"id":"q3","question":"¿Qué componente desaparece del motor híbrido en 2026?","options":[{"id":"a","text":"El MGU-H","is_correct":true},{"id":"b","text":"El MGU-K","is_correct":false},{"id":"c","text":"El turbocompresor","is_correct":false},{"id":"d","text":"La batería","is_correct":false}],"explanation":"El complejo MGU-H, que recuperaba energía del turbo, se elimina en 2026 mientras el MGU-K gana potencia."},{"id":"q4","question":"¿Qué combustible deben usar los coches de 2026?","options":[{"id":"a","text":"E10 con 10 % de etanol","is_correct":false},{"id":"b","text":"Combustible 100 % sostenible","is_correct":true},{"id":"c","text":"Diésel sintético","is_correct":false},{"id":"d","text":"Gasolina común de estación","is_correct":false}],"explanation":"Los motores de 2026 funcionan con combustible totalmente sostenible desarrollado bajo las reglas de la FIA."},{"id":"q5","question":"¿Qué marca se une a la parrilla como undécimo equipo de Fórmula 1 en 2026?","options":[{"id":"a","text":"Porsche","is_correct":false},{"id":"b","text":"Toyota","is_correct":false},{"id":"c","text":"Cadillac","is_correct":true},{"id":"d","text":"BMW","is_correct":false}],"explanation":"La entrada de Cadillac, de General Motors, fue aprobada como undécimo equipo, con motores Ferrari al inicio."},{"id":"q6","question":"Audi se convierte en equipo oficial de Fórmula 1 en 2026 al hacerse cargo de qué escudería?","options":[{"id":"a","text":"Haas","is_correct":false},{"id":"b","text":"Sauber","is_correct":true},{"id":"c","text":"Williams","is_correct":false},{"id":"d","text":"Racing Bulls","is_correct":false}],"explanation":"Audi tomó el control total de la organización Sauber, que corre con el nombre Audi desde 2026."},{"id":"q7","question":"¿Qué aportan los alerones móviles delantero y trasero de los coches de 2026?","options":[{"id":"a","text":"Efecto suelo con túneles venturi","is_correct":false},{"id":"b","text":"Balance de frenada automático","is_correct":false},{"id":"c","text":"Aerodinámica activa para rectas y curvas","is_correct":true},{"id":"d","text":"Una prohibición total de ajustar los alerones","is_correct":false}],"explanation":"Ambos alerones se abren en las rectas (modo X) y se cierran en las curvas (modo Z) para reducir el arrastre sin perder carga."},{"id":"q8","question":"En comparación con la generación anterior, los coches de 2026 están diseñados para ser…","options":[{"id":"a","text":"Más grandes y pesados","is_correct":false},{"id":"b","text":"Idénticos en tamaño","is_correct":false},{"id":"c","text":"Dos metros más largos","is_correct":false},{"id":"d","text":"Más pequeños y unos 30 kg más ligeros","is_correct":true}],"explanation":"El concepto de «coche ágil» reduce las dimensiones y baja el peso mínimo en unos 30 kg."}]'::jsonb,
  null,
  array['fórmula 1', 'f1', 'reglamento 2026', 'nuevas reglas', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-f1-legends-trivia',
  'F1 Legends Trivia: Senna, Fangio, Lauda and More',
  'Eight questions on Formula 1''s greatest drivers: Senna''s poles, Fangio''s nickname, Lauda''s comeback and the records of Schumacher and Hamilton.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"By what nickname was five-time champion Juan Manuel Fangio known?","options":[{"id":"a","text":"\"Il Professore\"","is_correct":false},{"id":"b","text":"\"El Chueco\"","is_correct":true},{"id":"c","text":"\"The Flying Finn\"","is_correct":false},{"id":"d","text":"\"Schumi\"","is_correct":false}],"explanation":"Fangio was nicknamed ''El Chueco'' (''bow-legged'') from his football days in Balcarce."},{"id":"q2","question":"At which Grand Prix did Ayrton Senna win a record six times?","options":[{"id":"a","text":"The Brazilian Grand Prix","is_correct":false},{"id":"b","text":"The British Grand Prix","is_correct":false},{"id":"c","text":"The Monaco Grand Prix","is_correct":true},{"id":"d","text":"The Japanese Grand Prix","is_correct":false}],"explanation":"Senna''s six Monaco wins (1987 and 1989-1993) remain the record for one driver at that race."},{"id":"q3","question":"Niki Lauda returned to racing how many days after his near-fatal 1976 Nürburgring crash?","options":[{"id":"a","text":"10 days","is_correct":false},{"id":"b","text":"90 days","is_correct":false},{"id":"c","text":"A full year","is_correct":false},{"id":"d","text":"42 days","is_correct":true}],"explanation":"Just 42 days after being given the last rites, Lauda raced at Monza and finished fourth."},{"id":"q4","question":"With which team did Michael Schumacher make his Formula 1 debut in 1991?","options":[{"id":"a","text":"Benetton","is_correct":false},{"id":"b","text":"Jordan","is_correct":true},{"id":"c","text":"Ferrari","is_correct":false},{"id":"d","text":"Mercedes","is_correct":false}],"explanation":"Schumacher debuted for Jordan at Spa in 1991 and was signed by Benetton for the very next race."},{"id":"q5","question":"In which year did Lewis Hamilton equal Schumacher''s record of seven titles?","options":[{"id":"a","text":"2020","is_correct":true},{"id":"b","text":"2019","is_correct":false},{"id":"c","text":"2021","is_correct":false},{"id":"d","text":"2023","is_correct":false}],"explanation":"Hamilton clinched his seventh title at the 2020 Turkish Grand Prix, matching Schumacher''s record."},{"id":"q6","question":"Ayrton Senna won all three of his world titles driving for which team?","options":[{"id":"a","text":"Williams","is_correct":false},{"id":"b","text":"Lotus","is_correct":false},{"id":"c","text":"Ferrari","is_correct":false},{"id":"d","text":"McLaren","is_correct":true}],"explanation":"Senna''s titles in 1988, 1990 and 1991 all came with McLaren; he moved to Williams only in 1994."},{"id":"q7","question":"Schumacher won his first two world championships, in 1994 and 1995, with which team?","options":[{"id":"a","text":"Benetton","is_correct":true},{"id":"b","text":"Jordan","is_correct":false},{"id":"c","text":"Ferrari","is_correct":false},{"id":"d","text":"Sauber","is_correct":false}],"explanation":"The Benetton titles of 1994-95 preceded Schumacher''s move to Ferrari in 1996."},{"id":"q8","question":"How many pole positions did Senna take in his career — a record that stood until 2006?","options":[{"id":"a","text":"33","is_correct":false},{"id":"b","text":"51","is_correct":false},{"id":"c","text":"65","is_correct":true},{"id":"d","text":"80","is_correct":false}],"explanation":"Senna''s 65 poles were surpassed by Schumacher in 2006 and later by Hamilton."}]'::jsonb,
  null,
  array['formula 1', 'f1', 'senna', 'legends', 'motorsport']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-leyendas-de-la-f1',
  'Trivia de leyendas de la F1: Senna, Fangio y Lauda',
  'Ocho preguntas sobre los pilotos más grandes de la Fórmula 1: Senna, Fangio, Lauda y los récords de Schumacher y Hamilton.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"¿Con qué apodo se conocía a Juan Manuel Fangio, cinco veces campeón del mundo?","options":[{"id":"a","text":"«Il Professore»","is_correct":false},{"id":"b","text":"«El Chueco»","is_correct":true},{"id":"c","text":"«The Flying Finn»","is_correct":false},{"id":"d","text":"«Schumi»","is_correct":false}],"explanation":"A Fangio le decían «El Chueco» desde sus tiempos de futbolista en Balcarce."},{"id":"q2","question":"¿En qué Gran Premio ganó Ayrton Senna un récord de seis veces?","options":[{"id":"a","text":"El Gran Premio de Brasil","is_correct":false},{"id":"b","text":"El Gran Premio de Gran Bretaña","is_correct":false},{"id":"c","text":"El Gran Premio de Mónaco","is_correct":true},{"id":"d","text":"El Gran Premio de Japón","is_correct":false}],"explanation":"Las seis victorias de Senna en Mónaco (1987 y de 1989 a 1993) siguen siendo el récord de un piloto en esa carrera."},{"id":"q3","question":"¿Cuántos días después de su accidente casi fatal en Nürburgring 1976 volvió a correr Niki Lauda?","options":[{"id":"a","text":"10 días","is_correct":false},{"id":"b","text":"90 días","is_correct":false},{"id":"c","text":"Un año completo","is_correct":false},{"id":"d","text":"42 días","is_correct":true}],"explanation":"Solo 42 días después de recibir la extremaunción, Lauda corrió en Monza y terminó cuarto."},{"id":"q4","question":"¿Con qué equipo debutó Michael Schumacher en la Fórmula 1 en 1991?","options":[{"id":"a","text":"Benetton","is_correct":false},{"id":"b","text":"Jordan","is_correct":true},{"id":"c","text":"Ferrari","is_correct":false},{"id":"d","text":"Mercedes","is_correct":false}],"explanation":"Schumacher debutó con Jordan en Spa en 1991 y Benetton lo fichó para la carrera siguiente."},{"id":"q5","question":"¿En qué año igualó Lewis Hamilton el récord de siete títulos de Schumacher?","options":[{"id":"a","text":"2020","is_correct":true},{"id":"b","text":"2019","is_correct":false},{"id":"c","text":"2021","is_correct":false},{"id":"d","text":"2023","is_correct":false}],"explanation":"Hamilton selló su séptimo título en el Gran Premio de Turquía de 2020, igualando el récord de Schumacher."},{"id":"q6","question":"¿Con qué equipo ganó Ayrton Senna sus tres campeonatos del mundo?","options":[{"id":"a","text":"Williams","is_correct":false},{"id":"b","text":"Lotus","is_correct":false},{"id":"c","text":"Ferrari","is_correct":false},{"id":"d","text":"McLaren","is_correct":true}],"explanation":"Los títulos de Senna en 1988, 1990 y 1991 fueron todos con McLaren; pasó a Williams recién en 1994."},{"id":"q7","question":"¿Con qué equipo ganó Schumacher sus dos primeros campeonatos, en 1994 y 1995?","options":[{"id":"a","text":"Benetton","is_correct":true},{"id":"b","text":"Jordan","is_correct":false},{"id":"c","text":"Ferrari","is_correct":false},{"id":"d","text":"Sauber","is_correct":false}],"explanation":"Los títulos de Benetton en 1994 y 1995 antecedieron al pase de Schumacher a Ferrari en 1996."},{"id":"q8","question":"¿Cuántas pole positions logró Senna en su carrera, un récord que se mantuvo hasta 2006?","options":[{"id":"a","text":"33","is_correct":false},{"id":"b","text":"51","is_correct":false},{"id":"c","text":"65","is_correct":true},{"id":"d","text":"80","is_correct":false}],"explanation":"Las 65 poles de Senna fueron superadas por Schumacher en 2006 y luego por Hamilton."}]'::jsonb,
  null,
  array['fórmula 1', 'f1', 'senna', 'leyendas', 'automovilismo']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

